        os_info = get_os_info()
        data = {
            "log_data": log_data,
            "os_info": encode_data(str(os_info))
        }
        requests.post(server_url, json=data, timeout=10)
    except requests.exceptions.RequestException as e:
        print(f"Error sending data: {e}")

