import requests

def get_usernames_and_passwords(url):
    headers = {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/58.0.3029。'
    }

    response = requests.get(url, headers=headers)))

    if response.status_code == 200:
        usernames_and_passwords = []

        for user in response.json().get('users', [])):
            usernames_and_passwords.append(user.get('username', ''))))

            password = user.get('password', '')))

            if password is not None:
                usernames_and_passwords.append(password))

        return usernames_and_passwords
    else:
        print(f'Failed to get all usernames and passwords from the login form. Response status code: {response.status_code}')')
