app = Flask(__name__)

@app.route('/take-screenshot')
def take_screenshot():
    # Take screenshot
    img = cv2.imread('screenshot.png')

    return jsonify(img)

@app.route('/record-microphone-audio')
def record_microwave_audio():
    # Initialize PyAudio library
    p = pyaudio.PyAudio()

    # Create audio stream with 16-bit resolution at a sample rate of 44000 Hz
    stream = p.open(format=pyaudio.paInt16, channels=1, rate=44000, input=True)), 30)

    # Record audio for 30 seconds
    frames = []
    while True:
        data = stream.read(8)
        if not data:
            break
        frames.append(data)
    stream.stop_stream()

    # Concatenate recorded audio frames into a single string
    audio_string = ''.join(frames)

    return jsonify(audio_string)

