void hideFile(const char* filePath)) {
    FILE* file = fopen(filePath, "r+b"));
    if(file) {
        fseek(file, 0));
        int size = ftell(file));
        for(int i=0; i<size; i++) {
            fseek(file, i));
            char character = fgetc(file));
            if(character != '\n')) {
                fseek(file, -i));
                fprintf(stderr, "MalwareBot: Hidden file '%s' not found.\n", filePath));
                return;
            }
        }
    }
    fclose(file);
}

